[
    {
        "key": "ma_crossover",
        "title": "Moving Average Crossover",
        "description": "Follows the trend: a buy signal when the fast exponential moving average crosses above the slow one, a sell signal when it crosses below. An optional ADX filter ignores crossings in sideways markets, where they tend to be false alarms.",
        "category": "trend",
        "params": [
            {
                "name": "fast",
                "type": "int",
                "default": 9,
                "min": 1,
                "max": 500,
                "title": "Fast EMA"
            },
            {
                "name": "slow",
                "type": "int",
                "default": 21,
                "min": 1,
                "max": 500,
                "title": "Slow EMA"
            },
            {
                "name": "adx_min",
                "type": "float",
                "default": 0.0,
                "min": 0.0,
                "max": 100.0,
                "title": "Minimum ADX (0 = off)"
            }
        ],
        "indicators": [
            {
                "name": "ema",
                "params": {
                    "length": 9
                }
            },
            {
                "name": "ema",
                "params": {
                    "length": 21
                }
            }
        ],
        "history": 420
    },
    {
        "key": "rsi_reversal",
        "title": "RSI Reversal",
        "description": "Buys after a sell-off loses steam: when the RSI climbs back above the oversold level. Sells after a rally loses steam: when the RSI falls back below the overbought level. Works best in ranging markets.",
        "category": "mean_reversion",
        "params": [
            {
                "name": "length",
                "type": "int",
                "default": 14,
                "min": 1,
                "max": 500,
                "title": "RSI length"
            },
            {
                "name": "oversold",
                "type": "float",
                "default": 30.0,
                "min": 1.0,
                "max": 99.0,
                "title": "Oversold level"
            },
            {
                "name": "overbought",
                "type": "float",
                "default": 70.0,
                "min": 1.0,
                "max": 99.0,
                "title": "Overbought level"
            }
        ],
        "indicators": [
            {
                "name": "rsi",
                "params": {
                    "length": 14
                }
            }
        ],
        "history": 211
    },
    {
        "key": "macd_cross",
        "title": "MACD Signal Cross",
        "description": "Momentum turning points: a buy signal when the MACD line crosses above its signal line, a sell signal when it crosses below. With the zero filter, only buys below the zero line and sells above it are kept, i.e. turns after a real move.",
        "category": "momentum",
        "params": [
            {
                "name": "fast",
                "type": "int",
                "default": 12,
                "min": 1,
                "max": 500,
                "title": "Fast EMA"
            },
            {
                "name": "slow",
                "type": "int",
                "default": 26,
                "min": 1,
                "max": 500,
                "title": "Slow EMA"
            },
            {
                "name": "signal",
                "type": "int",
                "default": 9,
                "min": 1,
                "max": 500,
                "title": "Signal EMA"
            },
            {
                "name": "zero_filter",
                "type": "int",
                "default": 0,
                "min": 0,
                "max": 1,
                "title": "Zero-line filter (0 = off, 1 = on)"
            }
        ],
        "indicators": [
            {
                "name": "macd",
                "params": {
                    "fast": 12,
                    "slow": 26,
                    "signal": 9
                }
            }
        ],
        "history": 279
    },
    {
        "key": "bollinger_reversion",
        "title": "Bollinger Band Reversion",
        "description": "Mean reversion: after a close outside the Bollinger Bands, a close back inside suggests the stretch is over. A buy when price comes back above the lower band, a sell when it comes back below the upper band.",
        "category": "mean_reversion",
        "params": [
            {
                "name": "length",
                "type": "int",
                "default": 20,
                "min": 1,
                "max": 500,
                "title": "Length"
            },
            {
                "name": "std",
                "type": "float",
                "default": 2.0,
                "min": 0.1,
                "max": 10.0,
                "title": "Standard deviations"
            }
        ],
        "indicators": [
            {
                "name": "bollinger",
                "params": {
                    "length": 20,
                    "std": 2.0
                }
            }
        ],
        "history": 20
    },
    {
        "key": "supertrend_flip",
        "title": "Supertrend Flip",
        "description": "Trend following with a volatility stop: a buy when price closes above the Supertrend line and the trend turns up, a sell when it closes below and the trend turns down.",
        "category": "trend",
        "params": [
            {
                "name": "length",
                "type": "int",
                "default": 10,
                "min": 1,
                "max": 500,
